@bp.route("/update-weight", methods=["POST"])
@require_auth
def update_weight():
    data = request.get_json(silent=True) or {}
    weight, error_key = _parse_weight(data.get("weight"))

    if error_key:
        return jsonify({"error": t(error_key)}), 400


    last_sess = UserSession.query.filter_by(user_id=current_user.id)\
        .order_by(UserSession.created_at.desc()).first()

    # Kiloyu kanonik profile yaz + profil TAM ise BMR/TDEE/hedefi yeniden hesapla
    # (ortak yardımcı; /checkin ile aynı davranış). Profil eksikse türetilmiş
    # hedefleri BOZMA — bkz. _apply_weight_to_profile (L2).
    bmr, tdee, target_calories, profile_ready = _apply_weight_to_profile(weight, last_sess)

    # Gün sınırı Istanbul gününe göre (CLAUDE.md): UTC gece-yarısı kullanmak
    # Istanbul 00:00–03:00 arası check-in'i bir önceki güne sokar ve "bugünü
    # güncelle" dalı atlanıp yinelenen satır eklenirdi (F1).
    today_start, today_end = utc_day_bounds(app_today())
    today_checkin = WeeklyCheckIn.query.filter(
        WeeklyCheckIn.user_id == current_user.id,
        WeeklyCheckIn.created_at >= today_start,
        WeeklyCheckIn.created_at < today_end,
    ).first()
    if today_checkin:
        today_checkin.weight = weight
    else:
        db.session.add(WeeklyCheckIn(user_id=current_user.id, weight=weight))

    db.session.commit()

    # Kilo güncellemesi de bir check-in sayılır → "Haftalık Check-in" görevini ver
    # (günde bir kez; zaten claimliyse None — 1.1).
    quest_result = complete_quest_for_user(current_user.id, "checkin_done")

    resp = {
        "bmr": round(bmr) if bmr is not None else None,
        "tdee": round(tdee) if tdee is not None else None,
        "target_calories": round(target_calories) if target_calories is not None else None,
        "profile_incomplete": not profile_ready,
    }
    if quest_result:
        resp["quest_awarded"] = quest_result
    return jsonify(resp)


@bp.route("/api/activity/log", methods=["POST"])
@require_auth
@auth_write_limit
def log_daily_activity():
    data = request.get_json(silent=True) or {}
    steps = _to_int(data.get("steps", 0), 0)  # sayısal olmayan/boş → 0 (500 yerine)
    intensity = data.get("intensity", "moderate")

    if intensity not in MET_CONFIG:
        return jsonify({"error": t("route.invalid_intensity")}), 400
    if steps <= 0:
        return jsonify({"error": t("route.steps_positive")}), 400

    weight = current_user.weight or 70
    height = current_user.height or 170
    calories, distance, duration = calculate_activity_calories(steps, intensity, weight, height)

    today_key = app_today().isoformat()
    # "Bugünün aktivitesi" TEK bir niceliktir (adım + yoğunluk). Eski idempotency
    # anahtarı (user_id, date_key, intensity) idi; yoğunluk açılır-menüsü
    # değiştikçe light/moderate/brisk için AYRI satır yaratıyor, today_activity de
    # kalorileri bunlar üzerinden TOPLAYARAK çift/üç sayım yapıyordu (M3). Artık
    # günün TÜM satırlarını silip tek taze satır yazıyoruz → günde tam bir satır.
    DailyActivity.query.filter_by(
        user_id=current_user.id, date_key=today_key
    ).delete(synchronize_session=False)
    db.session.add(DailyActivity(
        user_id=current_user.id, steps=steps, intensity=intensity,
        calories_burned=calories, distance_km=distance,
        duration_min=duration, date_key=today_key
    ))
    try:
        db.session.commit()
    except IntegrityError:
        # Yarış: eşzamanlı iki istek de aynı güne satır ekledi; uq_daily_activity
        # (user_id, date_key — C4: intensity kısıtta YOK, farklı intensity'ler de
        # çakışır) ikinci INSERT'i reddetti. Rollback edip günün satırını güncelle.
        db.session.rollback()
        existing = DailyActivity.query.filter_by(
            user_id=current_user.id, date_key=today_key
        ).order_by(DailyActivity.id.desc()).first()
        if existing is None:
            raise
        existing.steps = steps
        existing.intensity = intensity
        existing.calories_burned = calories
        existing.distance_km = distance
        existing.duration_min = duration
        db.session.commit()

    return jsonify({
        "message": t("route.steps_logged", steps=steps),
        "calories_burned": calories,
        "distance_km": distance,
        "duration_min": duration
    })


@bp.route("/api/activity/today")
@require_auth
def today_activity():
    today_key = app_today().isoformat()
    wearable = WearableActivityLog.query.filter_by(
        user_id=current_user.id, date_key=today_key
    ).order_by(WearableActivityLog.updated_at.desc(), WearableActivityLog.id.desc()).first()
    if wearable is not None:
        return jsonify({
            "source": "wearable",
            "provider": wearable.provider,
            "total_calories": round(wearable.calories_burned or 0, 1),
            "total_steps": wearable.steps or 0,
            "total_distance": 0,
            "entries": [{
                "intensity": "wearable", "steps": wearable.steps or 0,
                "calories_burned": wearable.calories_burned,
                "distance_km": 0, "duration_min": wearable.active_minutes,
                "resting_heart_rate": wearable.resting_heart_rate,
                "hrv_rmssd": wearable.hrv_rmssd,
            }]
        })

    # Günün TEK (en yeni) aktivite satırını al — TOPLAMA YAPMA. log_daily_activity
    # artık günde tek satır tutsa da, eski çoklu-satır (yoğunluk başına) veriye
    # karşı da en yenisini seçmek çift sayımı kesin olarak önler (M3).
    activity = DailyActivity.query.filter_by(
        user_id=current_user.id, date_key=today_key
    ).order_by(DailyActivity.id.desc()).first()

    if activity is None:
        return jsonify({
            "source": "manual",
            "provider": None,
            "total_calories": 0, "total_steps": 0,
            "total_distance": 0, "entries": []
        })

    return jsonify({
        "source": "manual",
        "provider": None,
        "total_calories": round(activity.calories_burned or 0, 1),
        "total_steps": activity.steps or 0,
        "total_distance": round(activity.distance_km or 0, 2),
        "entries": [{
            "intensity": activity.intensity, "steps": activity.steps,
            "calories_burned": activity.calories_burned,
            "distance_km": activity.distance_km, "duration_min": activity.duration_min,
        }]
    })


